"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";

type Topic = { id: string; title: string; cefrLevel: string };
type Word = { id: string; lemma: string; cefrLevel?: string | null };

export function CmsExerciseLearningLinksManager({ exerciseId, initialTopics, initialWords, topics }: { exerciseId: string; initialTopics: Topic[]; initialWords: Word[]; topics: Topic[] }) {
  const router = useRouter();
  const [selectedTopics, setSelectedTopics] = useState(initialTopics);
  const [selectedWords, setSelectedWords] = useState(initialWords);
  const [topicId, setTopicId] = useState("");
  const [wordQuery, setWordQuery] = useState("");
  const [wordMatches, setWordMatches] = useState<Word[]>([]);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const topicIds = useMemo(() => new Set(selectedTopics.map((item) => item.id)), [selectedTopics]);
  const wordIds = useMemo(() => new Set(selectedWords.map((item) => item.id)), [selectedWords]);
  useEffect(() => { if (wordQuery.trim().length < 2) { setWordMatches([]); return; } const timeout = window.setTimeout(() => { void fetch(`/api/admin/vocabulary?q=${encodeURIComponent(wordQuery)}`).then((response) => response.ok ? response.json() : null).then((payload: { data?: Word[] } | null) => setWordMatches(payload?.data ?? []) ).catch(() => undefined); }, 250); return () => window.clearTimeout(timeout); }, [wordQuery]);
  const save = async () => { setBusy(true); setMessage(""); try { const response = await fetch(`/api/admin/exercises/${exerciseId}/learning-links`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ grammarTopicIds: selectedTopics.map((item) => item.id), wordIds: selectedWords.map((item) => item.id) }) }); const payload = await response.json().catch(() => null); if (!response.ok) throw new Error(payload?.error ?? "Unable to save learning links."); setMessage("Learning links saved."); router.refresh(); } catch (reason) { setMessage(reason instanceof Error ? reason.message : "Unable to save learning links."); } finally { setBusy(false); } };
  return <section className="mt-6 rounded-2xl border border-slate-200 bg-white p-5"><h2 className="text-xl font-bold text-slate-950">Learning links</h2><p className="mt-1 text-sm text-slate-600">Tag this exercise with central grammar topics and vocabulary so review, reporting and content checks use canonical records.</p><div className="mt-4 grid gap-4 lg:grid-cols-2"><div><label className="text-sm font-semibold text-slate-800">Grammar topic<select value={topicId} onChange={(event) => setTopicId(event.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2"><option value="">Choose a topic</option>{topics.filter((topic) => !topicIds.has(topic.id)).map((topic) => <option key={topic.id} value={topic.id}>{topic.cefrLevel} · {topic.title}</option>)}</select></label><button type="button" onClick={() => { const topic = topics.find((item) => item.id === topicId); if (topic) { setSelectedTopics((current) => [...current, topic]); setTopicId(""); } }} disabled={!topicId || busy} className="mt-2 rounded border border-blue-300 px-3 py-1.5 text-sm font-semibold text-blue-700 disabled:opacity-50">Add grammar</button><div className="mt-3 flex flex-wrap gap-2">{selectedTopics.map((topic) => <span key={topic.id} className="rounded-full bg-violet-50 px-2.5 py-1 text-xs text-violet-900">{topic.cefrLevel} · {topic.title} <button type="button" aria-label={`Remove ${topic.title}`} onClick={() => setSelectedTopics((items) => items.filter((item) => item.id !== topic.id))} className="ml-1 font-bold">×</button></span>)}</div></div><div><label className="text-sm font-semibold text-slate-800">Vocabulary search<input value={wordQuery} onChange={(event) => setWordQuery(event.target.value)} placeholder="Type at least two letters" className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2" /></label>{wordMatches.length ? <div className="mt-2 flex flex-wrap gap-2">{wordMatches.filter((word) => !wordIds.has(word.id)).map((word) => <button key={word.id} type="button" onClick={() => { setSelectedWords((current) => [...current, word]); setWordQuery(""); setWordMatches([]); }} className="rounded border border-blue-200 bg-blue-50 px-2.5 py-1 text-sm text-blue-800">+ {word.lemma}</button>)}</div> : null}<div className="mt-3 flex flex-wrap gap-2">{selectedWords.map((word) => <span key={word.id} className="rounded-full bg-blue-50 px-2.5 py-1 text-xs text-blue-900">{word.lemma} <button type="button" aria-label={`Remove ${word.lemma}`} onClick={() => setSelectedWords((items) => items.filter((item) => item.id !== word.id))} className="ml-1 font-bold">×</button></span>)}</div></div></div><div className="mt-5 flex flex-wrap items-center gap-3"><button type="button" onClick={() => void save()} disabled={busy} className="rounded-lg bg-blue-700 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">{busy ? "Saving…" : "Save learning links"}</button>{message ? <p role="status" className="text-sm text-slate-600">{message}</p> : null}</div></section>;
}
